def create_workspace(fibery_host, workspace_name, auth_type, api_token, rate_limit_per_minute=None, **_extra):
    import json, os, datetime, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0089000" if __import__("os").path.isdir("./environment_mix/0089000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        return prefix + "".join(secrets.choice(_B32) for _ in range(26))

    def _norm_host(h):
        h2 = h.strip()
        if h2.endswith("/"):
            h2 = h2[:-1]
        return h2

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # --- Validation ---
    if not isinstance(fibery_host, str) or not fibery_host.strip():
        return _err("VALIDATION_ERROR", "fibery_host must be a non-empty string", field="fibery_host")
    host = _norm_host(fibery_host)
    if not re.match(r"^https?://", host):
        return _err("VALIDATION_ERROR", "fibery_host must start with http:// or https://", field="fibery_host")

    if not isinstance(workspace_name, str) or not workspace_name.strip():
        return _err("VALIDATION_ERROR", "workspace_name must be a non-empty string", field="workspace_name")
    ws_name = workspace_name.strip()

    if auth_type != "api_token":
        return _err("VALIDATION_ERROR", "auth_type must be 'api_token'", field="auth_type", allowed=["api_token"])

    if not isinstance(api_token, str) or not api_token.strip():
        return _err("VALIDATION_ERROR", "api_token must be a non-empty string when auth_type=api_token", field="api_token")

    if rate_limit_per_minute is None:
        rate_limit_per_minute = 60
    if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 1 or rate_limit_per_minute > 600:
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer between 1 and 600", field="rate_limit_per_minute")

    ws_rows = _load("workspaces.json")
    if not isinstance(ws_rows, list):
        ws_rows = []

    # Enforce schema constraint: unique(fibery_host)
    for w in ws_rows:
        if not isinstance(w, dict):
            continue
        existing_host = w.get("fibery_host")
        if isinstance(existing_host, str) and _norm_host(existing_host) == host:
            return _err(
                "CONFLICT",
                "Workspace connection already exists for this fibery_host (unique constraint: fibery_host).",
                rule="unique(fibery_host)",
                existing_workspace_id=w.get("id"),
                existing_fibery_host=existing_host,
            )

    # Store token as ciphertext placeholder (never store plaintext). This datastore doesn't support real encryption;
    # store a non-reversible marker that preserves "ciphertext exists" behavior.
    token_ciphertext = "enc:" + secrets.token_hex(16)

    new_row = {
        "id": _new_id("fbr_ws_"),
        "fibery_host": host,
        "workspace_name": ws_name,
        "auth_type": "api_token",
        "api_token_ciphertext": token_ciphertext,
        "status": "active",
        "last_schema_sync_at": None,
        "schema_etag": None,
        "rate_limit_per_minute": rate_limit_per_minute,
        "created_at": now,
        "updated_at": now,
    }

    ws_rows.append(new_row)
    _save("workspaces.json", ws_rows)

    return new_row

def update_workspace(workspace_id, status=None, api_token=None, rate_limit_per_minute=None, **_extra):
    import json, os, datetime, re, secrets, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0089000" if __import__("os").path.isdir("./environment_mix/0089000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    if not isinstance(workspace_id, str) or not re.match(r"^fbr_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is invalid")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, error")

    if api_token is not None:
        if not isinstance(api_token, str) or len(api_token.strip()) < 1:
            return _err("VALIDATION_ERROR", "api_token must be a non-empty string")

    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int):
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer")
        if rate_limit_per_minute < 1 or rate_limit_per_minute > 600:
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 600")

    workspaces = _load("workspaces.json")
    idx = None
    for i, ws in enumerate(workspaces):
        if isinstance(ws, dict) and ws.get("id") == workspace_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    ws = workspaces[idx]
    now = _now()

    # lifecycle transitions
    if status is not None and status != ws.get("status"):
        current = ws.get("status")
        allowed = {
            "active": ("disabled", "error"),
            "disabled": ("active",),
            "error": ("active", "disabled"),
        }
        if current not in allowed or status not in allowed[current]:
            return _err("INVALID_TRANSITION", "Status transition not allowed",
                        from_status=current, to_status=status)

        ws["status"] = status

    # update token (store ciphertext)
    if api_token is not None:
        salt = secrets.token_bytes(16)
        digest = hashlib.sha256(salt + api_token.encode("utf-8")).digest()
        ws["api_token_ciphertext"] = "sha256$" + base64.b64encode(salt + digest).decode("ascii")

    if rate_limit_per_minute is not None:
        ws["rate_limit_per_minute"] = rate_limit_per_minute

    # No success without effect
    if status is None and api_token is None and rate_limit_per_minute is None:
        return _err("VALIDATION_ERROR", "No mutable fields provided to update")

    ws["updated_at"] = now
    workspaces[idx] = ws
    _save("workspaces.json", workspaces)

    return {"workspace": ws}

def list_tool_invocations(workspace_id=None, tool_name=None, status=None, started_at_gte=None, started_at_lte=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0089000" if __import__("os").path.isdir("./environment_mix/0089000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # accept Z
            s2 = s.replace("Z", "+00:00")
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # Validate filters
    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^fbr_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id is invalid")

    allowed_tool_names = set(["current_date", "list_databases", "describe_database", "query_database", "create_entity", "update_entity"])
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in allowed_tool_names:
            return _err("VALIDATION_ERROR", "tool_name is invalid")

    if status is not None:
        if not isinstance(status, str) or status not in ("started", "succeeded", "failed"):
            return _err("VALIDATION_ERROR", "status must be one of: started, succeeded, failed")

    dt_gte = _parse_dt(started_at_gte)
    if started_at_gte is not None and dt_gte is None:
        return _err("VALIDATION_ERROR", "started_at_gte must be an RFC3339 date-time string")
    dt_lte = _parse_dt(started_at_lte)
    if started_at_lte is not None and dt_lte is None:
        return _err("VALIDATION_ERROR", "started_at_lte must be an RFC3339 date-time string")
    if dt_gte and dt_lte and dt_lte < dt_gte:
        return _err("VALIDATION_ERROR", "started_at_lte must be >= started_at_gte")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500")

    # Cursor decoding: base64url of JSON {"offset": int}
    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or len(page_token) == 0:
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string")
        try:
            pad = "=" * ((4 - (len(page_token) % 4)) % 4)
            raw = base64.urlsafe_b64decode((page_token + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "page_token is invalid")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "page_token is invalid")

    inv = _load("tool_invocations.json")
    rows = [r for r in inv if isinstance(r, dict)]

    # Apply filters
    def _row_dt(r):
        s = r.get("started_at")
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    filtered = []
    for r in rows:
        if workspace_id is not None and r.get("workspace_id") != workspace_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        dtr = _row_dt(r)
        if dt_gte is not None and dtr is not None and dtr < dt_gte:
            continue
        if dt_gte is not None and dtr is None:
            continue
        if dt_lte is not None and dtr is not None and dtr > dt_lte:
            continue
        if dt_lte is not None and dtr is None:
            continue
        filtered.append(r)

    # Sort by started_at desc, then id desc for stability
    def _sort_key(r):
        dtr = _row_dt(r)
        # None sorts last
        ts = dtr.timestamp() if dtr else float("-inf")
        return (ts, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        token_obj = {"offset": next_offset}
        tok = base64.urlsafe_b64encode(json.dumps(token_obj, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")
        next_cursor = tok

    return {
        "items": page,
        "metadata": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }
